const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.rows)) {
  store.rows = [];
}

const incoming = $json.body ?? $json;
const data = incoming.data ?? incoming;

const row = {
  id: `${Date.now()}-${Math.floor(Math.random() * 100000)}`,
  received_at: new Date().toISOString(),
  event: incoming.event ?? 'machine_energy_telemetry',
  source: incoming.source ?? 'node-red',
  topic: incoming.topic ?? 'smartfactory/MC-01/energy/telemetry',
  machine_id: data.machine_id ?? null,
  active_power_kw: data.active_power_kw ?? null,
  power_factor: data.power_factor ?? null,
  frequency_hz: data.frequency_hz ?? null,
  voltage_v: data.voltage_v ?? null,
  current_a: data.current_a ?? null,
  payload: incoming
};

store.rows.push(row);

// Keep last 10,000 rows in n8n workflow static data
if (store.rows.length > 10000) {
  store.rows = store.rows.slice(-10000);
}

return [{
  json: {
    ok: true,
    saved: true,
    table: 'workflow_static_data.rows',
    total_rows: store.rows.length,
    latest: row
  }
}];
